<?php
namespace Tests\Feature;use App\Models\{Institution,Survey,User};use Database\Seeders\RolesAndPermissionsSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class HistoricalComparisonTest extends TestCase{use RefreshDatabase;protected function setUp():void{parent::setUp();$this->seed(RolesAndPermissionsSeeder::class);}public function test_compatible_surveys_produce_before_after_changes():void{$u=User::factory()->create();$u->assignRole('Analyst');$i=Institution::create(['name'=>'T','slug'=>'t']);$c=$i->campuses()->create(['name'=>'M','code'=>'M']);$b=$c->buildings()->create(['name'=>'B','code'=>'B']);$f=$b->floors()->create(['name'=>'G','code'=>'G','level_number'=>0]);$fp=$f->floorPlans()->create(['uploaded_by'=>$u->id,'original_name'=>'p','file_path'=>'p','mime_type'=>'image/png','file_size'=>1,'version'=>1]);$surveys=[];foreach([-80,-60] as$n=>$rssi){$s=Survey::create(['floor_id'=>$f->id,'floor_plan_id'=>$fp->id,'created_by'=>$u->id,'name'=>'S'.$n]);$p=$s->points()->create(['floor_plan_id'=>$fp->id,'captured_by'=>$u->id,'x_normalized'=>.2+$n*.1,'y_normalized'=>.3,'source_type'=>'measured','collection_method'=>'manual','validation_status'=>'valid','captured_at'=>now()->addDays($n)]);$p->measurements()->create(['rssi_dbm'=>$rssi,'download_mbps'=>20+$n*20,'latency_ms'=>80-$n*40,'source_type'=>'measured','collection_method'=>'manual','captured_at'=>now()->addDays($n)]);$surveys[]=$s;}$this->actingAs($u)->postJson('/api/comparisons',['baseline_survey_id'=>$surveys[0]->id,'followup_survey_id'=>$surveys[1]->id])->assertCreated()->assertJsonPath('is_comparable',true)->assertJsonPath('changes.median_rssi_dbm',20);}}
